using System;
using System.Reflection;
using System.Linq;
using System.IO;

// Load Microsoft.Agents.AI
var agiDllPath = Directory.GetFiles(
    Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), ".nuget", "packages", "microsoft.agents.ai"),
    "Microsoft.Agents.AI.dll",
    SearchOption.AllDirectories
).First();

Console.WriteLine($"Loading: {agiDllPath}");
var asm = Assembly.LoadFrom(agiDllPath);

Console.WriteLine($"\n=== Microsoft.Agents.AI Public Types ===\n");
foreach (var t in asm.GetExportedTypes().OrderBy(t => t.FullName))
{
    Console.WriteLine($"\n{t.FullName}");

    // Constructors
    var ctors = t.GetConstructors(BindingFlags.Public | BindingFlags.Instance);
    if (ctors.Length > 0)
    {
        foreach (var ctor in ctors)
        {
            var @params = string.Join(", ", ctor.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
            Console.WriteLine($"  [ctor] ({@params})");
        }
    }

    // Methods
    var methods = t.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly)
        .Where(m => !m.IsSpecialName);
    foreach (var m in methods.OrderBy(m => m.Name))
    {
        var @params = string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
        Console.WriteLine($"  {m.Name}({@params}) : {m.ReturnType.Name}");
    }

    // Properties
    var props = t.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly);
    foreach (var p in props.OrderBy(p => p.Name))
    {
        Console.WriteLine($"  [prop] {p.PropertyType.Name} {p.Name}");
    }
}

// Load Microsoft.Extensions.AI
var extAiDllPath = Directory.GetFiles(
    Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), ".nuget", "packages", "microsoft.extensions.ai"),
    "Microsoft.Extensions.AI.dll",
    SearchOption.AllDirectories
).First();

Console.WriteLine($"\n\nLoading: {extAiDllPath}");
var extAsm = Assembly.LoadFrom(extAiDllPath);

Console.WriteLine($"\n=== Microsoft.Extensions.AI Key Types (AIFunction, ChatOptions) ===\n");
var keyTypes = extAsm.GetExportedTypes()
    .Where(t => t.Name.Contains("AIFunction") || t.Name.Contains("ChatOptions") || t.Name.Contains("Tool"))
    .OrderBy(t => t.FullName)
    .ToList();

foreach (var t in keyTypes)
{
    Console.WriteLine($"\n{t.FullName}");

    // Constructors
    var ctors = t.GetConstructors(BindingFlags.Public | BindingFlags.Instance);
    if (ctors.Length > 0)
    {
        foreach (var ctor in ctors)
        {
            var @params = string.Join(", ", ctor.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
            Console.WriteLine($"  [ctor] ({@params})");
        }
    }

    // Methods
    var methods = t.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly)
        .Where(m => !m.IsSpecialName);
    foreach (var m in methods.OrderBy(m => m.Name))
    {
        var @params = string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
        Console.WriteLine($"  {m.Name}({@params}) : {m.ReturnType.Name}");
