using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

var services = new ServiceCollection();
services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, apiKey));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();
var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

// --- Tools -----------------------------------------------------------

var notebook = new Notebook();
var webSearcher = new WebSearcher();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(webSearcher.SearchWeb),
    AIFunctionFactory.Create(notebook.SaveNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// --- Agent -----------------------------------------------------------

const string instructions = """
    You are a research assistant. When given a topic:
    1. Search the web for relevant information (make several searches with
       different queries to get broad coverage).
    2. Save the most important findings as notes using the note-taking tool.
    3. After gathering enough information, retrieve all your notes and
       produce a well-structured summary with key findings, organized by
       theme.
    Always cite the source URL for each finding you save.
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "Researches a topic by searching the web and summarizing findings",
    tools: tools,
    loggerFactory: loggerFactory,
    services: sp);

// --- Run -------------------------------------------------------------

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var session = new ChatClientAgentSession();
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session,
    runOptions,
    CancellationToken.None);

Console.WriteLine("\n📋 Research Summary\n" + new string('═', 60));

foreach (var message in response.Messages)
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.WriteLine(message.Text);
    }
}

Console.WriteLine(new string('═', 60));
Console.WriteLine($"\n📝 {notebook.Count} note(s) saved during research.\n");

return;

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var topic = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(topic)
        ? throw new InvalidOperationException("A research topic is required.")
        : topic;
}

// =====================================================================
// Tools
// =====================================================================

/// <summary>Simulates web search by querying a public search API.</summary>
sealed class WebSearcher
{
    private static readonly HttpClient Http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "application/json" },
        },
    };

    [Description("Search the web for a query and return a list of result snippets with URLs.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_redirect=1&no_html=1";
            var json = await Http.GetStringAsync(url);

            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;
            var sb = new StringBuilder();

            // Abstract (instant answer)
            var abs = root.GetProperty("Abstract").GetString();
            var absUrl = root.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrWhiteSpace(abs))
            {
                sb.AppendLine($"## Instant Answer\n{abs}\nSource: {absUrl}\n");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                var count = 0;
                foreach (var topic in topics.EnumerateArray())
                {
                    if (count >= 8) break;
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var link = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        sb.AppendLine($"- {text}");
                        if (!string.IsNullOrWhiteSpace(link))
                            sb.AppendLine($"  URL: {link}");
                        count++;
                    }
                }
            }

            return sb.Length > 0
                ? sb.ToString()
                : "No results found. Try a different or more specific query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

/// <summary>In-memory notebook for saving and retrieving research notes.</summary>
sealed class Notebook
{
    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

    public int Count => _notes.Count;

    [Description("Save a research note with a title and content. Use this to record important findings.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("Detailed content including source URLs")] string content)
    {
        _notes.Add((title, content, DateTime.UtcNow));
        return $"Note saved: \"{title}\" (total notes: {_notes.Count})";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            var (title, content, ts) = _notes[i];
            sb.AppendLine($"### Note {i + 1}: {title}");
            sb.AppendLine(content);
            sb.AppendLine();
        }
        return sb.ToString();
    }
}

