arguments.old_str:
using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

var services = new ServiceCollection();
services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, apiKey));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();
var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

// --- Tools -----------------------------------------------------------

var notebook = new Notebook();
var webSearcher = new WebSearcher();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(webSearcher.SearchWeb),
    AIFunctionFactory.Create(notebook.SaveNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// --- Agent -----------------------------------------------------------

const string instructions = """
    You are a research assistant. When given a topic:
    1. Search the web for relevant information (make several searches with
       different queries to get broad coverage).
    2. Save the most important findings as notes using the note-taking tool.
    3. After gathering enough information, retrieve all your notes and
       produce a well-structured summary with key findings, organized by
       theme.
    Always cite the source URL for each finding you save.
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "Researches a topic by searching the web and summarizing findings",
    tools: tools,
    loggerFactory: loggerFactory,
    services: sp);

// --- Run -------------------------------------------------------------

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var session = new ChatClientAgentSession();
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session,
    runOptions,
    CancellationToken.None);

Console.WriteLine("\n📋 Research Summary\n" + new string('═', 60));

foreach (var message in response.Messages)
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.WriteLine(message.Text);
    }
}

Console.WriteLine(new string('═', 60));
Console.WriteLine($"\n📝 {notebook.Count} note(s) saved during research.\n");

return;

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var topic = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(topic)
        ? throw new InvalidOperationException("A research topic is required.")
        : topic;
}

